const studentChoice=new Set('POL2108 POL2300 POL2302 POL3300 POL3301 POL3302 POL4100'.split(' '));
export function registrationExam(code,term){
 const official=termAnnouncements[term]?.[code];
 const old=examEvidence[code];
 const written=historicWritten[code];
 const label=official?.format||(old||studentChoice.has(code)?'คาดว่าสอบกา':written?'คาดว่าสอบเขียน':'ยังไม่ทราบรูปแบบสอบ');
 const url=official?.url||old?.url||written;
 const source=official?'ประกาศของภาคนี้':old||written?'หลักฐานย้อนหลัง':studentChoice.has(code)?'ข้อมูลที่นักศึกษาแชร์':'รอประกาศผู้สอน';
 return `<div><b>${e(label)}</b> · ${url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${source}</a>`:source}${code==='POL2104'?'<br><small>สอบซ่อม: มีข้อมูลจากนักศึกษาว่าสอบเขียน</small>':''}</div>`;
}
